1	import 'package:dio/dio.dart';
2	
3	import 'dio_error_code.dart';
4	import 'header_interceptor.dart';
5	
6	/// AD-4 — the one place retry policy lives. Retries only the 6 server
7	/// `retryable:true` codes (`error-taxonomy.md`); every other failure
8	/// (including the local `MalformedResponse`) surfaces once, unretried.
9	///
10	/// Design note (docs/input is silent on the schedule): fixed 500ms delay,
11	/// max 2 retries.
12	class RetryInterceptor extends Interceptor {
13	  RetryInterceptor(this._dio);
14	
15	  final Dio _dio;
16	
17	  /// The 6 server `retryable:true` codes — the only codes this interceptor
18	  /// ever retries.
19	  static const Set<String> retryableCodes = {
20	    'NETWORK_TIMEOUT',
21	    'NETWORK_OFFLINE',
22	    'PII_CHECK_FAILED',
23	    'EMBEDDING_FAILED',
24	    'AI_GENERATION_TIMEOUT',
25	    'RATE_LIMITED',
26	  };
27	
28	  /// Non-idempotent POSTs with no client-supplied idempotency key — a
29	  /// transparent retry here would silently resend the identical request
30	  /// (the same chat message content, or a second session-create) rather
31	  /// than surfacing the failure once to the caller. `dioErrorCodeOf` can
32	  /// return a retryable code for these from `DioException.type` alone
33	  /// (`NETWORK_TIMEOUT`/`NETWORK_OFFLINE`) even before any response body
34	  /// exists to carry the real `{code,message}`, so excluding by function
35	  /// name here is the only place this can be enforced.
36	  static const Set<String> neverRetriedFunctions = {
37	    'chat-messages-send',
38	    'chat-sessions-create',
39	  };
40	
41	  static const int maxRetries = 2;
42	  static const Duration retryDelay = Duration(milliseconds: 500);
43	
44	  static const _attemptKey = 'cerne_retry_attempt';
45	
46	  @override
47	  void onError(DioException err, ErrorInterceptorHandler handler) async {
48	    final attempt = attemptOf(err);
49	
50	    if (shouldRetry(err, attempt)) {
51	      await Future<void>.delayed(retryDelay);
52	      final options = err.requestOptions;
53	      options.extra[_attemptKey] = attempt + 1;
54	      try {
55	        final response = await _dio.fetch<dynamic>(options);
56	        handler.resolve(response);
57	      } on DioException catch (retryError) {
58	        handler.next(retryError);
59	      } catch (retryError) {
60	        // Any non-DioException thrown by the retried fetch must still reach
61	        // the caller through `handler`, never escape unhandled (RNF09).
62	        handler.next(
63	          DioException(
64	            requestOptions: options,
65	            error: retryError,
66	            type: DioExceptionType.unknown,
67	          ),
68	        );
69	      }
70	      return;
71	    }
72	
73	    handler.next(err);
74	  }
75	
76	  /// How many retries have already been attempted for this request.
77	  static int attemptOf(DioException err) =>
78	      (err.requestOptions.extra[_attemptKey] as int?) ?? 0;
79	
80	  /// The backend error `code` for [err] — delegates to the shared
81	  /// [dioErrorCodeOf] (also used by `ApiClient`) so a client-side timeout or
82	  /// a cancelled request is never misread as `NETWORK_OFFLINE` here.
83	  static String? errorCodeOf(DioException err) => dioErrorCodeOf(err);
84	
85	  /// Pure decision function, independently testable: retry only if the
86	  /// error's code is one of the 6 allowlisted codes, the max-retries
87	  /// budget isn't exhausted yet, and the request isn't one of the
88	  /// [neverRetriedFunctions].
89	  static bool shouldRetry(DioException err, int attempt) {
90	    final code = errorCodeOf(err);
91	    if (code == null || !retryableCodes.contains(code) || attempt >= maxRetries) {
92	      return false;
93	    }
94	    final function = HeaderInterceptor.functionNameOf(err.requestOptions.path);
95	    return !neverRetriedFunctions.contains(function);
96	  }
97	}
